import { apiFetch } from '../lib/api.js'

export interface NoteSummary {
  id: string
  path: string
  type: string
  name: string
  frontmatter: Record<string, unknown>
  updatedAt: string
}

export type VaultTree = Record<string, NoteSummary[]>

export function getVaultTree(vaultId: string): Promise<VaultTree> {
  return apiFetch(`/vaults/${vaultId}/tree`)
}

export interface NoteDetail {
  path: string
  frontmatter: Record<string, unknown>
  body: string
  updatedAt: string
}

export function getNote(vaultId: string, path: string): Promise<NoteDetail> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`)
}

export interface UpdateNoteInput {
  frontmatter?: Record<string, unknown>
  body?: string
}

export interface UpdateNoteResult {
  id: string
  path: string
  frontmatter: Record<string, unknown>
  body: string
  updatedAt: string
}

export function updateNote(vaultId: string, path: string, input: UpdateNoteInput): Promise<UpdateNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`, { method: 'PUT', body: JSON.stringify(input) })
}

export interface CreateNoteInput {
  type: string
  name: string
}

export interface CreateNoteResult {
  id: string
  path: string
  type: string
  name: string
}

export function createNote(vaultId: string, input: CreateNoteInput): Promise<CreateNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes`, { method: 'POST', body: JSON.stringify(input) })
}

export interface RenameNoteInput {
  from: string
  to: string
}

export interface RenameNoteResult {
  id: string
  path: string
  type: string
  name: string
}

export function renameNote(vaultId: string, input: RenameNoteInput): Promise<RenameNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes-rename`, { method: 'POST', body: JSON.stringify(input) })
}

export interface DeleteNoteResult {
  status: string
  id: string
}

export function deleteNote(vaultId: string, path: string): Promise<DeleteNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`, { method: 'DELETE' })
}

import { useEffect, useRef } from 'react'
import { useOutletContext, useParams } from 'react-router'
import { useNote } from '../../hooks/useNote.js'
import { useUpdateNote } from '../../hooks/useUpdateNote.js'
import { useVaultTree } from '../../hooks/useVaultTree.js'
import { useCodeMirrorEditor } from '../../hooks/useCodeMirrorEditor.js'
import { canEdit } from '../../api/vaults.js'
import type { Vault } from '../../api/vaults.js'
import { PropertyPanel } from '../../components/vault/PropertyPanel.js'

const SAVE_DEBOUNCE_MS = 1200

export function NoteView() {
  const { vaultId } = useParams<{ vaultId: string }>()
  const path = useParams()['*']
  const vault = useOutletContext<Vault | undefined>()
  const note = useNote(vaultId!, path!)

  if (note.isPending) return null
  if (note.isError) return <div className="p-8 text-muted-foreground">Note not found.</div>

  // Conservative default: unknown access (vault undefined) => read-only.
  const readOnly = !canEdit(vault?.access)

  return (
    <NoteEditor
      // Remount key is the full note identity (vault + path) plus the edit
      // capability: keying on path alone would reuse a stale editor across a
      // cross-vault switch to the same path, and would also miss a change in
      // the user's access to this note (e.g. a live share revocation).
      key={`${vaultId}/${path}/${readOnly}`}
      vaultId={vaultId!}
      path={path!}
      vaultName={vault?.name}
      frontmatter={note.data!.frontmatter}
      initialBody={note.data!.body}
      readOnly={readOnly}
    />
  )
}

interface NoteEditorProps {
  vaultId: string
  path: string
  vaultName: string | undefined
  frontmatter: Record<string, unknown>
  initialBody: string
  readOnly: boolean
}

function NoteEditor({ vaultId, path, vaultName, frontmatter, initialBody, readOnly }: NoteEditorProps) {
  const updateNote = useUpdateNote(vaultId, path)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
    }
  }, [])

  function handleChange(newBody: string) {
    // Belt-and-suspenders: the editor is non-editable when readOnly, so this
    // shouldn't fire from user input — but never PUT an edit the server will
    // 404 anyway.
    if (readOnly) return
    if (timeoutRef.current) clearTimeout(timeoutRef.current)
    timeoutRef.current = setTimeout(() => {
      updateNote.mutate({ body: newBody })
    }, SAVE_DEBOUNCE_MS)
  }

  const tree = useVaultTree(vaultId)
  const wikilinkTargets = tree.data ? Object.values(tree.data).flat().map((n) => n.path) : []
  const editorRef = useCodeMirrorEditor({ doc: initialBody, onChange: handleChange, readOnly, wikilinkTargets })

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-border px-8 py-4 text-sm text-muted-foreground">
        {vaultName ?? vaultId} / <span className="text-foreground">{path}</span>
        {readOnly && <span className="ml-2 text-xs uppercase tracking-wide">· read-only</span>}
      </div>
      <div className="border-b border-border px-8 py-4">
        <PropertyPanel
          vaultId={vaultId}
          path={path}
          initialFrontmatter={frontmatter}
          readOnly={readOnly}
        />
      </div>
      <div ref={editorRef} className="flex-1 overflow-auto" />
    </div>
  )
}

import { useQuery } from '@tanstack/react-query'
import { getVaultTree } from '../api/notes.js'
import type { ApiError } from '../lib/api.js'
import type { VaultTree } from '../api/notes.js'

export function useVaultTree(vaultId: string) {
  return useQuery<VaultTree, ApiError>({
    queryKey: ['vault-tree', vaultId],
    queryFn: () => getVaultTree(vaultId),
  })
}

import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { RouterProvider } from 'react-router'
import { router } from './router.js'

const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: false } },
})

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>
  )
}
